package pl.zagranietyper;import com.fasterxml.jackson.databind.ObjectMapper;import pl.zagranietyper.config.AppConfig;import pl.zagranietyper.parser.FootballEventPlayerPositiveSyntaxAdapter;import pl.zagranietyper.repository.*;import pl.zagranietyper.service.FootballEventPlayerResolver;import java.util.*;import java.util.regex.*;
/** Conservative read-only coverage estimate; it never emits settlement updates. */
public final class FootballFixturePlayerStatisticsCoverageAuditMain {private static final Pattern EXPLICIT=Pattern.compile("^(.+?) (?:powyzej ([0-9]+(?:[.,][0-9]+)?)|co najmniej ([0-9]+)|odda (?:co najmniej )?([0-9]+)?) (celn(?:y|e|ych) )?strzal(?:ow|y|u)?$");private FootballFixturePlayerStatisticsCoverageAuditMain(){}public static void main(String[]a){var db=new Database(AppConfig.fromEnvironment());var repo=new FootballFixturePlayerStatisticsRepository(db,new ObjectMapper());var resolver=new FootballEventPlayerResolver();var eventParser=new FootballEventPlayerPositiveSyntaxAdapter();Map<Long,List<pl.zagranietyper.model.FootballFixturePlayerStatisticsSnapshot.Player>>cache=new HashMap<>();int scorer=0,assist=0,shots=0,on=0,saves=0,fouls=0,offsides=0,other=0;for(var c:new FootballSettlementRepository(db).findPendingApiFootballCandidates()){if(!Set.of("FT","AET","PEN").contains(c.statusShort()))continue;var players=cache.computeIfAbsent(c.fixtureId(),repo::loadPlayers);if(players.isEmpty())continue;var ids=players.stream().map(p->new FootballEventPlayerResolver.PlayerIdentity(p.playerId(),p.playerName())).toList();var ep=eventParser.parse(c.tipTitle());if(ep.parsed()){var rr=resolver.resolveIdentities(ep.playerLabel(),ids);if(!rr.resolved())continue;var p=find(players,rr.playerId());if(p==null||!p.appearanceConfirmed())continue;if(ep.family()==FootballEventPlayerPositiveSyntaxAdapter.Family.ANYTIME_SCORER&&p.goals()!=null)scorer++;if(ep.family()==FootballEventPlayerPositiveSyntaxAdapter.Family.PLAYER_ASSIST&&p.assists()!=null)assist++;continue;}String n=FootballEventPlayerResolver.normalize(c.tipTitle()).replaceFirst("^(betbuilder|superbet|superbets) ","");Matcher m=EXPLICIT.matcher(n);if(m.matches()){String label=m.group(1);var rr=resolver.resolveIdentities(label,ids);if(!rr.resolved())continue;var p=find(players,rr.playerId());if(p==null)continue;boolean target=m.group(5)!=null;Integer value=target?p.shotsOnTarget():p.shotsTotal();if(value==null)continue;double threshold=m.group(2)!=null?Double.parseDouble(m.group(2).replace(',','.')):m.group(3)!=null?Integer.parseInt(m.group(3))-1d:m.group(4)==null||m.group(4).isBlank()?0d:Integer.parseInt(m.group(4))-1d;if(value>threshold||p.appearanceConfirmed()){if(target)on++;else shots++;}continue;}if(n.matches("^.+ (?:interwencji|obron).*$"))saves++;else if(n.matches("^.+ faul.*$"))fouls++;else if(n.matches("^.+ spalon.*$"))offsides++;else if(n.matches("^.+ (?:tackl|odbior|podan|drybl).*$"))other++;}System.out.println("anytimeScorerSafe="+scorer);System.out.println("shotsTotalSafe="+shots);System.out.println("shotsOnTargetSafe="+on);System.out.println("assistsSafe="+assist);System.out.println("savesPotentialNeedsGrammarAudit="+saves);System.out.println("foulsPotentialNeedsGrammarAudit="+fouls);System.out.println("offsidesPotentialNeedsGrammarAudit="+offsides);System.out.println("otherPotentialNeedsGrammarAudit="+other);}private static pl.zagranietyper.model.FootballFixturePlayerStatisticsSnapshot.Player find(List<pl.zagranietyper.model.FootballFixturePlayerStatisticsSnapshot.Player>p,long id){return p.stream().filter(x->Objects.equals(x.playerId(),id)).findFirst().orElse(null);}}
